<span class="line" data-line="228"><span class="ln">228</span><span style="color:#569CD6">           EXEC CICS</span><span style="color:#569CD6"> READ</span><span style="color:#569CD6"> FILE</span><span style="color:#D4D4D4">(</span><span style="color:#CE9178">'DOGEVSAM'</span><span style="color:#D4D4D4">) </span><span style="color:#569CD6">INTO</span><span style="color:#D4D4D4">(</span><span style="color:#9CDCFE">LIMIT-RECORD</span><span style="color:#D4D4D4">)</span></span>
