<span class="line" data-line="248"><span class="ln">248</span><span style="color:#569CD6">           MOVE</span><span style="color:#CCCCCC"> WS-TOTAL-DEC </span><span style="color:#569CD6">TO</span><span style="color:#CCCCCC"> LTOT-DEC.</span></span>
